@Test
public void testNormal() throws AnalysisException {
    DataDescription desc = new DataDescription("testTable", null, Lists.newArrayList("abc.txt"), null, null, null, false, null);
    desc.analyze("testDb");
    Assert.assertEquals("APPEND DATA INFILE ('abc.txt') INTO TABLE testTable", desc.toString());
    desc = new DataDescription("testTable", null, Lists.newArrayList("abc.txt"), null, null, null, true, null);
    desc.analyze("testDb");
    Assert.assertEquals("APPEND DATA INFILE ('abc.txt') NEGATIVE INTO TABLE testTable", desc.toString());
    desc = new DataDescription("testTable", null, Lists.newArrayList("abc.txt", "bcd.txt"), null, null, null, true, null);
    desc.analyze("testDb");
    Assert.assertEquals("APPEND DATA INFILE ('abc.txt', 'bcd.txt') NEGATIVE INTO TABLE testTable", desc.toString());
    desc = new DataDescription("testTable", null, Lists.newArrayList("abc.txt"), Lists.newArrayList("col1", "col2"), null, null, true, null);
    desc.analyze("testDb");
    Assert.assertEquals("APPEND DATA INFILE ('abc.txt') NEGATIVE INTO TABLE testTable (col1, col2)", desc.toString());
    Assert.assertEquals("testTable", desc.getTableName());
    Assert.assertEquals("[col1, col2]", desc.getFileFieldNames().toString());
    Assert.assertEquals("[abc.txt]", desc.getFilePaths().toString());
    Assert.assertTrue(desc.isNegative());
    Assert.assertNull(desc.getColumnSeparator());
    Expr whereExpr = new BinaryPredicate(BinaryPredicate.Operator.EQ, new IntLiteral(1), new IntLiteral(1));
    desc = new DataDescription("testTable", null, Lists.newArrayList("abc.txt"), Lists.newArrayList("col1", "col2"), new ColumnSeparator(","), "csv", null, false, null, whereExpr, LoadTask.MergeType.MERGE, whereExpr, null);
    desc.analyze("testDb");
    Assert.assertEquals("MERGE DATA INFILE ('abc.txt') INTO TABLE testTable COLUMNS TERMINATED BY ',' (col1, col2) WHERE 1 = 1 DELETE ON 1 = 1", desc.toString());
    Assert.assertEquals("1 = 1", desc.getWhereExpr().toSql());
    Assert.assertEquals("1 = 1", desc.getDeleteCondition().toSql());
    Assert.assertEquals(",", desc.getColumnSeparator());
    desc = new DataDescription("testTable", null, Lists.newArrayList("abc.txt", "bcd.txt"), Lists.newArrayList("col1", "col2"), new ColumnSeparator("\t"), null, true, null);
    desc.analyze("testDb");
    Assert.assertEquals("APPEND DATA INFILE ('abc.txt', 'bcd.txt') NEGATIVE INTO TABLE testTable" + " COLUMNS TERMINATED BY '\t' (col1, col2)", desc.toString());
    // hive \x01 column separator
    desc = new DataDescription("testTable", null, Lists.newArrayList("abc.txt", "bcd.txt"), Lists.newArrayList("col1", "col2"), new ColumnSeparator("\\x01"), null, true, null);
    desc.analyze("testDb");
    Assert.assertEquals("APPEND DATA INFILE ('abc.txt', 'bcd.txt') NEGATIVE INTO TABLE testTable" + " COLUMNS TERMINATED BY '\\x01' (col1, col2)", desc.toString());
    // with partition
    desc = new DataDescription("testTable", new PartitionNames(false, Lists.newArrayList("p1", "p2")), Lists.newArrayList("abc.txt"), null, null, null, false, null);
    desc.analyze("testDb");
    Assert.assertEquals("APPEND DATA INFILE ('abc.txt') INTO TABLE testTable PARTITIONS (p1, p2)", desc.toString());
    // alignment_timestamp func
    List<Expr> params = Lists.newArrayList();
    params.add(new StringLiteral("day"));
    params.add(new SlotRef(null, "k2"));
    BinaryPredicate predicate = new BinaryPredicate(Operator.EQ, new SlotRef(null, "k1"), new FunctionCallExpr("alignment_timestamp", params));
    desc = new DataDescription("testTable", new PartitionNames(false, Lists.newArrayList("p1", "p2")), Lists.newArrayList("abc.txt"), Lists.newArrayList("k2", "k3"), null, null, false, Lists.newArrayList((Expr) predicate));
    desc.analyze("testDb");
    String sql = "APPEND DATA INFILE ('abc.txt') INTO TABLE testTable PARTITIONS (p1, p2) (k2, k3)" + " SET (`k1` = alignment_timestamp('day', `k2`))";
    Assert.assertEquals(sql, desc.toString());
    // replace_value func
    params.clear();
    params.add(new StringLiteral("-"));
    params.add(new StringLiteral("10"));
    predicate = new BinaryPredicate(Operator.EQ, new SlotRef(null, "k1"), new FunctionCallExpr("replace_value", params));
    desc = new DataDescription("testTable", new PartitionNames(false, Lists.newArrayList("p1", "p2")), Lists.newArrayList("abc.txt"), Lists.newArrayList("k2", "k3"), null, null, false, Lists.newArrayList((Expr) predicate));
    desc.analyze("testDb");
    sql = "APPEND DATA INFILE ('abc.txt') INTO TABLE testTable PARTITIONS (p1, p2) (k2, k3)" + " SET (`k1` = replace_value('-', '10'))";
    Assert.assertEquals(sql, desc.toString());
    // replace_value null
    params.clear();
    params.add(new StringLiteral(""));
    params.add(new NullLiteral());
    predicate = new BinaryPredicate(Operator.EQ, new SlotRef(null, "k1"), new FunctionCallExpr("replace_value", params));
    desc = new DataDescription("testTable", new PartitionNames(false, Lists.newArrayList("p1", "p2")), Lists.newArrayList("abc.txt"), Lists.newArrayList("k2", "k3"), null, null, false, Lists.newArrayList((Expr) predicate));
    desc.analyze("testDb");
    sql = "APPEND DATA INFILE ('abc.txt') INTO TABLE testTable PARTITIONS (p1, p2) (k2, k3)" + " SET (`k1` = replace_value('', NULL))";
    Assert.assertEquals(sql, desc.toString());
    // data from table and set bitmap_dict
    params.clear();
    params.add(new SlotRef(null, "k2"));
    predicate = new BinaryPredicate(Operator.EQ, new SlotRef(null, "k1"), new FunctionCallExpr("bitmap_dict", params));
    desc = new DataDescription("testTable", new PartitionNames(false, Lists.newArrayList("p1", "p2")), "testHiveTable", false, Lists.newArrayList(predicate), null, LoadTask.MergeType.APPEND, null);
    desc.analyze("testDb");
    sql = "APPEND DATA FROM TABLE testHiveTable INTO TABLE testTable PARTITIONS (p1, p2) SET (`k1` = bitmap_dict(`k2`))";
    Assert.assertEquals(sql, desc.toSql());
}

