    ColocateTableIndex colocateTableIndex = createColocateIndex(groupId, Lists.newArrayList(1L, 2L, 3L, 4L, 1L, 2L, 3L, 4L, 1L, 2L, 3L, 4L, 1L, 2L, 3L));
