    List<List<Long>> balancedBackendsPerBucketSeq = Lists.newArrayList();
    List<Long> allAvailBackendIds = Lists.newArrayList(1L, 2L, 3L, 4L, 5L, 6L, 7L, 8L, 9L);
    boolean changed = (Boolean) Deencapsulation.invoke(balancer, "balance", groupId, allAvailBackendIds, colocateTableIndex, infoService, balancedBackendsPerBucketSeq);
    System.out.println(balancedBackendsPerBucketSeq);
    List<List<Long>> expected = Lists.partition(Lists.newArrayList(9L, 5L, 3L, 4L, 6L, 8L, 7L, 6L, 1L, 2L, 9L, 4L, 1L, 2L, 3L), 3);
    Assert.assertTrue(changed);
    Assert.assertEquals(expected, balancedBackendsPerBucketSeq);
    // 2. balance a already balanced group
    colocateTableIndex = createColocateIndex(groupId, Lists.newArrayList(9L, 8L, 7L, 8L, 6L, 5L, 9L, 4L, 1L, 2L, 3L, 4L, 1L, 2L, 3L));
    Deencapsulation.setField(colocateTableIndex, "group2Schema", group2Schema);
    balancedBackendsPerBucketSeq.clear();
    changed = (Boolean) Deencapsulation.invoke(balancer, "balance", groupId, allAvailBackendIds, colocateTableIndex, infoService, balancedBackendsPerBucketSeq);
    System.out.println(balancedBackendsPerBucketSeq);
    Assert.assertFalse(changed);
    Assert.assertTrue(balancedBackendsPerBucketSeq.isEmpty());
}

